  "config.categorias.categoria_mae": { pt: "Categoria-mãe", en: "Parent category", es: "Categoría principal", fr: "Catégorie parente", de: "Übergeordnete Kategorie", it: "Categoria principale", zh: "父类别", ru: "Родительская категория", uk: "Батьківська категорія", pl: "Kategoria nadrzędna", hi: "मूल श्रेणी", ko: "상위 카테고리", ar: "الفئة الرئيسية", bn: "মূল বিভাগ", id: "Kategori induk" },
  "config.categorias.imagem_title": { pt: "Imagem da categoria", en: "Category image", es: "Imagen de la categoría", fr: "Image de la catégorie", de: "Kategoriebild", it: "Immagine della categoria", zh: "类别图片", ru: "Изображение категории", uk: "Зображення категорії", pl: "Obraz kategorii", hi: "श्रेणी छवि", ko: "카테고리 이미지", ar: "صورة الفئة", bn: "বিভাগের ছবি", id: "Gambar kategori" },
  "config.categorias.remover_title": { pt: "Remover categoria", en: "Remove category", es: "Eliminar categoría", fr: "Supprimer la catégorie", de: "Kategorie entfernen", it: "Rimuovi categoria", zh: "移除类别", ru: "Удалить категорию", uk: "Видалити категорію", pl: "Usuń kategorię", hi: "श्रेणी हटाएं", ko: "카테고리 제거", ar: "إزالة الفئة", bn: "বিভাগ অপসারণ করুন", id: "Hapus kategori" },
  "config.categorias.nome_obrigatorio": { pt: "Indique um nome para a categoria.", en: "Please enter a name for the category.", es: "Indique un nombre para la categoría.", fr: "Indiquez un nom pour la catégorie.", de: "Bitte geben Sie einen Namen für die Kategorie an.", it: "Indica un nome per la categoria.", zh: "请为该类别输入名称。", ru: "Укажите название категории.", uk: "Вкажіть назву категорії.", pl: "Podaj nazwę kategorii.", hi: "श्रेणी के लिए एक नाम दर्ज करें।", ko: "카테고리 이름을 입력하세요.", ar: "يرجى إدخال اسم للفئة.", bn: "বিভাগের জন্য একটি নাম দিন।", id: "Masukkan nama untuk kategori." },

